    def test_register_model_creates_entry(self, registry):
        """Registration populates internal model map."""
        registry.register_model("test-model", {"task_types": ["simple"]}, priority=1)
        assert "test-model" in registry.list_models()
        assert registry.get_model("test-model") is not None

    def test_register_duplicate_updates_not_duplicates(self, registry):
        """Re-registering same ID updates config without duplication."""
        registry.register_model("dup-model", {"task_types": ["simple"]}, priority=1)
        registry.register_model("dup-model", {"task_types": ["complex"]}, priority=2)
        models = registry.list_models()
        assert models.count("dup-model") == 1
        assert registry.get_model("dup-model")["priority"] == 2

    def test_unregister_removes_entry(self, populated_registry):
        """Unregistering removes model from all internal structures."""
        populated_registry.unregister_model("gpt-4o")
        assert "gpt-4o" not in populated_registry.list_models()

    def test_unregister_nonexistent_raises(self, registry):
        """Unregistering unknown model raises KeyError."""
        with pytest.raises(KeyError):
            registry.unregister_model("ghost-model")

    def test_schema_after_bulk_operations(self, populated_registry):
        """Schema remains valid after mixed register/unregister."""
