# ── Concurrency & Threshold Tests ──────────────────────────────────────────
class TestConcurrencyThresholds:
    """Validate load tracking and threshold enforcement."""

    def test_initial_load_zero(self, registry):
        """Fresh registry has zero load."""
        assert registry.get_load() == 0.0

    def test_increment_load(self, registry):
        """Incrementing load increases counter."""
        registry.increment_load()
        assert registry.get_load() == 1.0

    def test_decrement_load(self, registry):
        """Decrementing load decreases counter."""
        registry.increment_load()
        registry.increment_load()
        registry.decrement_load()
        assert registry.get_load() == 1.0

    def test_decrement_below_zero_raises(self, registry):
        """Decrementing below zero raises ValueError."""
        with pytest.raises(ValueError):
            registry.decrement_load()

    def test_threshold_exceeded(self, registry):
        """Load above threshold triggers rejection."""
        registry.set_threshold(5)
        for _ in range(5):
            registry.increment_load()
        assert registry.is_over_threshold() is True

    def test_threshold_not_exceeded(self, registry):
        """Load at threshold does not trigger rejection."""
        registry.set_threshold(5)
        for _ in range(4):
            registry.increment_load()
        assert registry.is_over_threshold() is False

    def test_concurrent_increments_are_atomic(self, registry):
        """100 concurrent increments must result in exactly 100."""
        with ThreadPoolExecutor(max_workers=10) as executor:
            futures = [executor.submit(registry.increment_load) for _ in range(100)]
            for f in as_completed(futures):
                f.result()
        assert registry.get_load() == 100.0

    def test_concurrent_mixed_operations(self, registry):
        """Concurrent inc/dec must maintain non-negative invariant."""
        def worker(ops):
            for _ in range(ops):
                registry.increment_load()
                registry.decrement_load()

        with ThreadPoolExecutor(max_workers=8) as executor:
            futures = [executor.submit(worker, 50) for _ in range(8)]
            for f in as_completed(futures):
                f.result()
        assert registry.get_load() == 0.0

    def test_concurrent_register_and_select(self, populated_registry):
        """Concurrent registration and selection must not corrupt state."""
        def register_worker():
            for i in range(10):
                populated_registry.register_model(
                    f"temp-{i}", {"task_types": ["simple"]}, priority=i
                )

        def select_worker():
            for _ in range(50):
                try:
                    populated_registry.select_model("simple")
                except (ValueError, RuntimeError):
                    pass

        with ThreadPoolExecutor(max_workers=4) as executor:
            futures = [
                executor.submit(register_worker),
                executor.submit(select_worker),
                executor.submit(select_worker),
                executor.submit(select_worker),
            ]
            for f in as_completed(futures):
                f.result()

        # Cleanup temp models
        for i in range(10):
            populated_registry.unregister_model(f"temp-{i}")
        assert len(populated_registry.list_models()) == 3


