    @settings(max_examples=20, suppress_health_check=[HealthCheck.too_slow])
    def test_load_never_negative_after_balanced_ops(self, registry, ops):
        """Property: balanced inc/dec never yields negative load."""
        for _ in range(ops):
            registry.increment_load()
        for _ in range(ops):
            registry.decrement_load()
