class TestPerformance:
    """Validate performance under load with timeouts."""

    @pytest.mark.timeout(5)
    def test_select_under_1000_models(self, registry):
        """Selection remains fast with many models."""
        for i in range(1000):
            registry.register_model(
                f"model-{i}",
                {"task_types": [f"task-{i % 10}"]},
                priority=i % 100,
            )
        start = time.time()
        for _ in range(100):
            registry.select_model("task-0")
        elapsed = time.time() - start
        assert elapsed < 2.0

    @pytest.mark.timeout(10)
    def test_concurrent_load_10000_ops(self, registry):
        """10k concurrent increments complete within timeout."""
        with ThreadPoolExecutor(max_workers=32) as executor:
            futures = [
                executor.submit(registry.increment_load) for _ in range(10000)
            ]
            for f in as_completed(futures):
                f.result()
        assert registry.get_load() == 10000.0


